/**
 * Terrain horizon masks.
 *
 * Two sources, one shape `{step, values, max, min, flat}`:
 *
 *  - measured: `data/terrain.json`, generated by `pipeline/build_terrain.py`
 *    from LOLA LDEM 80S (80 m/pixel). This is the real relief: 720 azimuths of
 *    apparent elevation, curvature included.
 *  - illustrative: a deterministic envelope from the `horizon` block of
 *    sites.json, used for the sites outside the polar DEM (the equator, the
 *    near side, the far side) and as a fallback when the file is missing.
 *
 * `terrainInfo()` tells the interface which one is in use, so no page claims a
 * measured mask it does not have.
 */

const STEP_DEG = 0.5;
const N = Math.round(360 / STEP_DEG);

function hashSeed(text) {
  let h = 2166136261;
  for (let i = 0; i < text.length; i += 1) {
    h ^= text.charCodeAt(i);
    h = Math.imul(h, 16777619);
  }
  return h >>> 0;
}

function mulberry32(seed) {
  let a = seed;
  return () => {
    a |= 0;
    a = (a + 0x6d2b79f5) | 0;
    let t = Math.imul(a ^ (a >>> 15), 1 | a);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

const cache = new Map();
const measured = new Set();
let terrainMeta = null;

/** Deterministic 720-sample horizon profile (degrees of elevation). */
export function horizonProfile(site) {
  if (cache.has(site.id)) return cache.get(site.id);

  const params = site.horizon || { max: 1, az: 0, rough: 0.4 };
  // A site standing on a massif looks DOWN on the surrounding terrain, so the
  // lowest horizon direction is below the horizontal: `floor` can be negative.
  const floor = params.floor ?? 0;
  const peakElevation = params.max ?? 0;
  const rand = mulberry32(hashSeed(site.id));
  const harmonics = [];
  for (let k = 1; k <= 5; k += 1) {
    harmonics.push({ n: k, amp: (0.15 + 0.35 * rand()) / k, phase: rand() * Math.PI * 2 });
  }

  const raw = new Float64Array(N);
  let lo = Infinity;
  let hi = -Infinity;
  for (let i = 0; i < N; i += 1) {
    const az = i * STEP_DEG;
    // Broad massif toward the dominant azimuth, plus ridged harmonics.
    const delta = ((az - params.az + 540) % 360) - 180;
    const lobe = Math.exp(-((delta / 42) ** 2));
    let shape = 0.55 + 0.45 * lobe;
    for (const h of harmonics) {
      shape += params.rough * 0.22 * h.amp * Math.sin((h.n * az * Math.PI) / 180 + h.phase);
    }
    raw[i] = shape;
    if (shape < lo) lo = shape;
    if (shape > hi) hi = shape;
  }

  const values = new Float64Array(N);
  const span = hi - lo || 1;
  for (let i = 0; i < N; i += 1) {
    const t = (raw[i] - lo) / span;
    values[i] = floor + (peakElevation - floor) * t;
  }

  const flat = peakElevation === 0 && floor === 0;
  const profile = { step: STEP_DEG, values, max: peakElevation, min: floor, flat };
  cache.set(site.id, profile);
  return profile;
}

/** Install a measured mask (for example from LOLA LDEM) for one site. */
export function registerHorizon(siteId, profile) {
  cache.set(siteId, profile);
  if (profile && profile.measured) measured.add(siteId);
}

/**
 * Install the whole `data/terrain.json` payload produced by the Python
 * pipeline. Values are hundredths of a degree, the same quantisation the
 * precomputed series use.
 */
export function installTerrain(payload) {
  if (!payload || !payload.sites) return 0;
  terrainMeta = {
    generated: payload.generated || null,
    source: payload.source || 'LOLA LDEM',
    dem: payload.dem || null,
    pixelM: payload.pixelM || null,
    rangeKm: payload.rangeKm || null,
    step: Number(payload.step) || STEP_DEG,
    sites: Object.keys(payload.sites).length,
  };
  const scale = Number(payload.scale) || 100;
  let count = 0;
  for (const [siteId, entry] of Object.entries(payload.sites)) {
    if (!entry || !Array.isArray(entry.values) || entry.values.length < 8) continue;
    const values = Float64Array.from(entry.values, (value) => value / scale);
    let max = -Infinity;
    let min = Infinity;
    for (const value of values) {
      if (value > max) max = value;
      if (value < min) min = value;
    }
    registerHorizon(siteId, {
      step: Number(payload.step) || STEP_DEG,
      values,
      max,
      min,
      flat: false,
      measured: true,
      elevation: entry.elevation ?? null,
    });
    count += 1;
  }
  return count;
}

/** Metadata of the terrain file, or null when the pages run on the envelope. */
export function terrainInfo() {
  return terrainMeta;
}

/** True when this site's mask is the LOLA one, not the illustrative envelope. */
export function isMeasured(siteId) {
  return measured.has(siteId);
}

/** Linear interpolation of the mask, wrapping across 359.5 -> 0. */
export function horizonAt(profile, az) {
  if (!profile || profile.flat) return 0;
  const f = ((az % 360) + 360) % 360 / profile.step;
  const i0 = Math.floor(f) % N;
  const i1 = (i0 + 1) % N;
  const frac = f - Math.floor(f);
  return profile.values[i0] * (1 - frac) + profile.values[i1] * frac;
}

export { STEP_DEG, N as HORIZON_POINTS };
